list-partial[enumerate](
    %#0规定为左结合的。#1 应解释为 #2%(
        Lambda.apply,
        Lambda.apply(x, y, z, w),
        Lambda.apply(
            parentheses(
                Lambda.apply(
                    parentheses(Lambda.apply(x, y)),
                    z
                )
            ),
            w
        )
    ),
    %运算优先级上 #0较 #1结合更加紧密。#2 应解释为 #3%(Lambda.apply, Type.Expr-UTLC.lambda, Type.Expr-UTLC.lambda(list-partial[none](@x, @y), Lambda.apply(x, y)),Type.Expr-UTLC.lambda(list-partial[none](@x, @y), parentheses(Lambda.apply(x, y))))
)
